@startuml

class Under_aged {
  + full_name : string
  + student_card : string
}

class Adult {
  + full_name : string
  + id_card : string
}

class Book {
  + title : string
  + author : string
}

class Borrow_History {
  + date : date
}

Under_aged "1" -- "0..4" Book : borrows
Adult "1" -- "0..4" Book : borrows
Under_aged "1" -- "*" Borrow_History : has
Adult "1" -- "*" Borrow_History : has
Borrow_History "*" -- "1" Book : involves

@enduml

